import math
relevant = {1, 3, 5, 7}
retrieved = [3, 2, 5, 1, 8, 7, 4, 6]

def recall_at_k(ret, rel, k):
    return len(set(ret[:k]) & rel) / len(rel)

def precision_at_k(ret, rel, k):
    return len(set(ret[:k]) & rel) / k

def mrr(ret, rel):
    for i, d in enumerate(ret, start=1):
        if d in rel:
            return 1.0 / i
    return 0.0

def dcg_at_k(ret, rel, k):
    s = 0.0
    for i, d in enumerate(ret[:k], start=1):
        if d in rel:
            s += 1.0 / math.log2(i + 1)
    return s

def ndcg_at_k(ret, rel, k):
    dcg = dcg_at_k(ret, rel, k)
    ideal = dcg_at_k(sorted(ret, key=lambda x: (x not in rel, 0)), rel, k)
    return dcg / ideal if ideal > 0 else 0.0

print('query 相关集 =', sorted(relevant))
for k in (1, 3, 5, 8):
    print('k=%d  Recall=%.4f  Precision=%.4f  NDCG=%.4f' % (
        k, recall_at_k(retrieved, relevant, k),
        precision_at_k(retrieved, relevant, k),
        ndcg_at_k(retrieved, relevant, k)))
print('MRR = %.4f' % mrr(retrieved, relevant))
